LESSON_JSON = "{\n \"id\": \"nonparamt1\",\n \"topicId\": \"nonparam-t1\",\n \"moduleId\": \"nonparam\",\n \"title\": \"Mann–Whitney U test\",\n \"breadcrumb\": \"Non-parametric methods → Two independent samples → Mann–Whitney U\",\n \"engine\": \"B\",\n \"engineName\": \"Pool observations, rank together, compare rank sums.\",\n \"version\": \"1.0\",\n \"status\": \"approved\",\n \"estMin\": 96,\n \"objectives\": [\n  \"Choose Mann–Whitney U for two independent ordinal-or-higher samples.\",\n  \"Pool observations and assign average ranks to ties.\",\n  \"Calculate both U statistics from pooled rank sums and verify their relationship.\",\n  \"State the null mean and variance, including the tie correction.\",\n  \"Interpret rejection without automatically claiming a median difference.\"\n ],\n \"prereq\": [\n  {\n   \"id\": \"p1\",\n   \"name\": \"Independent samples\",\n   \"why\": \"The groups contain different, unrelated observational units.\"\n  },\n  {\n   \"id\": \"p2\",\n   \"name\": \"Ordering and ranks\",\n   \"why\": \"The procedure replaces observations with positions in a pooled ordering.\"\n  },\n  {\n   \"id\": \"p3\",\n   \"name\": \"Mean and variance\",\n   \"why\": \"Large-sample inference standardises U using its null moments.\"\n  }\n ],\n \"traps\": [\n  \"Mann–Whitney is for independent groups; signed-rank is for paired observations.\",\n  \"Pool observations before ranking; do not rank groups separately.\",\n  \"U is not the rank sum R; subtract n(n+1)/2.\",\n  \"Tied observations receive average occupied ranks.\",\n  \"U₁+U₂=n₁n₂; this is not either individual U.\",\n  \"Rejection compares distributions generally; it is not always a median test.\"\n ],\n \"howto\": \"First pass: complete the pooled-rank worked example and both guided scenes. Revision: use the formulas, traps and revision sheet. Scope is two independent groups; paired observations belong to signed-rank/sign test, and three or more independent groups belong to Kruskal–Wallis.\",\n \"revision\": {\n  \"sheet\": [\n   \"Design: two independent samples; response at least ordinal; observations independent.\",\n   \"Pool N=n₁+n₂ observations and rank the combined list.\",\n   \"A tie occupying positions r,…,s receives average rank (r+s)/2.\",\n   \"R₁+R₂=N(N+1)/2.\",\n   \"U₁=R₁−n₁(n₁+1)/2; U₂=R₂−n₂(n₂+1)/2.\",\n   \"U₁+U₂=n₁n₂; conventional two-sided statistic is min(U₁,U₂).\",\n   \"E(U)=n₁n₂/2; no-tie Var(U)=n₁n₂(N+1)/12.\",\n   \"Tie correction factor: 1−Σ(t³−t)/(N³−N).\",\n   \"Z=(U−E(U))/√Var(U), with continuity correction if specified.\",\n   \"Median/location interpretation needs similarly shaped distributions.\"\n  ],\n  \"cards\": [\n   [\n    \"Design\",\n    \"Two independent samples\"\n   ],\n   [\n    \"Minimum scale\",\n    \"Ordinal\"\n   ],\n   [\n    \"Ties\",\n    \"Average occupied ranks\"\n   ],\n   [\n    \"U from R\",\n    \"U₁=R₁−n₁(n₁+1)/2\"\n   ],\n   [\n    \"U sum\",\n    \"U₁+U₂=n₁n₂\"\n   ],\n   [\n    \"Null mean\",\n    \"n₁n₂/2\"\n   ],\n   [\n    \"No-tie variance\",\n    \"n₁n₂(N+1)/12\"\n   ],\n   [\n    \"Interpretation\",\n    \"Distributional comparison; median shift needs common shape\"\n   ]\n  ],\n  \"tricks\": [\n   \"Pool first, rank second, split rank sums last.\",\n   \"Check U₁+U₂=n₁n₂.\",\n   \"Check pooled rank sum N(N+1)/2.\"\n  ],\n  \"shortcuts\": [\n   \"Σ ranks 1…N=N(N+1)/2.\",\n   \"E(U)=n₁n₂/2.\",\n   \"Var(U)=n₁n₂(N+1)/12 before tie correction.\"\n  ],\n  \"remember\": [\n   \"Independent groups → Mann–Whitney; paired measurements → signed-rank/sign test.\",\n   \"Do not interpret every rejection as a median difference.\"\n  ]\n },\n \"refs\": [\n  {\n   \"title\": \"Nonparametric Statistical Methods\",\n   \"where\": \"Two-sample location problems\",\n   \"site\": \"Hollander, Wolfe and Chicken\",\n   \"url\": \"\",\n   \"type\": \"Textbook\",\n   \"free\": false,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Rank-sum theory, ties and assumptions.\"\n  },\n  {\n   \"title\": \"NIST/SEMATECH e-Handbook of Statistical Methods\",\n   \"where\": \"Nonparametric methods\",\n   \"site\": \"NIST\",\n   \"url\": \"https://www.itl.nist.gov/div898/handbook/\",\n   \"type\": \"Free online textbook\",\n   \"free\": true,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Applied context for distribution-free procedures.\"\n  },\n  {\n   \"title\": \"Penn State STAT 415\",\n   \"where\": \"Nonparametric tests\",\n   \"site\": \"Penn State\",\n   \"url\": \"https://online.stat.psu.edu/stat415/\",\n   \"type\": \"Free online textbook\",\n   \"free\": true,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Accessible explanation of rank-based inference.\"\n  }\n ],\n \"mastery\": {\n  \"minQ\": 10,\n  \"pass\": 80,\n  \"draw\": 10,\n  \"fmtMin\": {\n   \"numeric\": 70,\n   \"multi\": 70\n  },\n  \"diffMix\": {\n   \"easy\": 3,\n   \"moderate\": 5,\n   \"hard\": 2\n  },\n  \"noHints\": true,\n  \"retestDays\": 7,\n  \"note\": \"Proposed platform settings, not an NTA rule. Overall 80%, with 70% floors on numerical and multi-statement items, answered without hints.\"\n },\n \"provenance\": \"June 2026 Paper 2 Q42 anchor: two independent groups of 15 executives. Full 30 scores are ranked together using average ranks for ties. Exact-rank computation gives R_ES=152.5, R_LC=312.5, U_ES=32.5, U_LC=192.5 and min(U)=32.5. Checks: pooled rank total 465 and U sum 225. Verification independently sorts and assigns rational average ranks. Null mean, no-tie variance and tie correction are asserted. Candidate response details are excluded. The Q42 anchor tests the independent two-sample design and the U statistic. The ten module variants cover the observed U value, U sum, null moments, ties, pooled rank total, paired-test contrast, Kruskal–Wallis contrast, rank-sum conversion and ordinal scale. Q33 is a parametric test-matching item and is not treated as a Non-parametric anchor.\",\n \"scenes\": [\n  {\n   \"kind\": \"foundation\",\n   \"id\": \"s0\",\n   \"mins\": 7,\n   \"title\": \"Start with the design\",\n   \"objective\": \"Identify the sample structure before choosing a test.\",\n   \"ask\": {\n    \"q\": \"Two different classes use two teaching methods. Independent or paired?\",\n    \"nudge\": \"Does any student appear in both groups?\"\n   },\n   \"body\": [\n    \"A test is chosen from how observations were collected. First decide whether groups are independent or whether each observation is linked to another. Then check whether the response has a meaningful order.\",\n    \"Mann–Whitney U compares two independent groups using the ordering of all observations. It does not require normal populations, but it does require independent observations and an ordinal-or-higher outcome.\"\n   ],\n   \"items\": [\n    {\n     \"ask\": \"Two separate classes each use one method. What is the design?\",\n     \"recall\": \"Two independent groups, if no student appears in both.\",\n     \"refresh\": [\n      \"An independent-samples design uses different observational units in the two groups. A person, animal or item must not contribute to both groups. If the same unit is measured twice, the two observations are linked and the independent-sample rank procedure is not the right analysis. Identify the unit before selecting a test.\",\n      \"An ordinal scale has a meaningful ordering even when the distances between adjacent categories are not known to be equal. Satisfaction categories such as low, medium and high can be ordered. Blood groups cannot. Mann–Whitney uses the order of observations, so nominal labels alone do not supply the information it needs.\"\n     ]\n    },\n    {\n     \"ask\": \"What information does a rank preserve?\",\n     \"recall\": \"Order, not numerical distance.\",\n     \"refresh\": [\n      \"Ranking replaces a measurement by its position in an ordered list. The operation keeps which observation is larger and discards how far apart the two values are. For example, scores 51 and 52 are adjacent just as scores 90 and 99 may be adjacent; their numerical gaps do not enter the rank calculation. This is why the pooled order is central to the test.\",\n      \"A nominal variable consists of labels with no natural smallest-to-largest arrangement. Assigning numbers to labels does not create a meaningful order: coding blood groups as 1, 2, 3 and 4 would be arbitrary. An ordinal variable has a defensible order, such as mild, moderate and severe. The rank procedure requires that defensible ordering.\"\n     ]\n    },\n    {\n     \"ask\": \"Can nominal categories be ranked meaningfully?\",\n     \"recall\": \"No. Nominal categories have no natural order.\",\n     \"refresh\": [\n      \"When the same participant contributes a before score and an after score, those values are connected by participant. Treating them as independent would break that connection and discard useful design information. A paired method works with within-participant changes; Wilcoxon signed-rank and the sign test are common nonparametric choices. Use Mann–Whitney only when the groups really are independent.\",\n      \"A rank is not a standardised score and it is not a percentile calculated separately within each group. It is the position in the combined ordered sample. Pooling puts every observation on the same scale, so a value from group 1 can receive a higher rank than a value from group 2. Separate rankings cannot express that cross-group comparison.\"\n     ]\n    }\n   ]\n  },\n  {\n   \"kind\": \"intuition\",\n   \"id\": \"s1\",\n   \"mins\": 7,\n   \"title\": \"Compare ordering rather than averages\",\n   \"objective\": \"Explain why pooled ranks can compare two groups.\",\n   \"ask\": {\n    \"q\": \"If group 1 tends to have larger observations, where will its ranks lie?\",\n    \"nudge\": \"Think about the combined ordered list.\"\n   },\n   \"body\": [\n    \"A few long waiting times can dominate an average. A rank procedure asks whether observations from one group tend to appear higher in the combined ordering than observations from the other group.\"\n   ],\n   \"scenario\": {\n    \"teaser\": \"Two independent groups receive different teaching methods.\",\n    \"title\": \"An executive training comparison\",\n    \"body\": [\n     \"A training manager randomly assigns executives to two teaching methods. Each executive contributes one final score, and no executive appears in both groups. The samples are independent. Scores may be skewed and a few unusually high values could distort a mean-based comparison. A rank procedure uses the ordering of all scores without requiring normal populations. Independence remains essential, and the result must be interpreted with attention to the shapes of the two distributions.\"\n    ],\n    \"q\": \"What feature makes a two-independent-sample rank test relevant?\",\n    \"answer\": \"Different executives appear in the two groups, so the samples are independent.\"\n   }\n  },\n  {\n   \"kind\": \"explore\",\n   \"id\": \"s2\",\n   \"mins\": 6,\n   \"title\": \"See the pooled ranking\",\n   \"objective\": \"Assign pooled ranks and handle a tie.\",\n   \"ask\": {\n    \"q\": \"What rank do both tied values 8 receive?\",\n    \"nudge\": \"Average positions 3 and 4.\"\n   },\n   \"body\": [\n    \"Group 1 values are 4, 8 and 10. Group 2 values are 5, 8 and 12. Pool them: 4, 5, 8, 8, 10, 12. Positions are 1, 2, 3, 4, 5, 6. The tied values occupy positions 3 and 4, so each receives rank 3.5.\",\n    \"Ranking each group separately would give each group ranks 1, 2 and 3 regardless of how high its values were. That destroys cross-group ordering.\"\n   ]\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s3\",\n   \"mins\": 9,\n   \"title\": \"The rank-sum and U formulas\",\n   \"objective\": \"Derive U from a group's pooled rank sum.\",\n   \"ask\": {\n    \"q\": \"Why does U₁+U₂ equal n₁n₂?\",\n    \"nudge\": \"Use the total rank sum and subtract both minimum rank sums.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"def\",\n     \"h\": \"Notation\",\n     \"body\": \"Let n₁ and n₂ be sample sizes, N=n₁+n₂, and R₁ and R₂ the pooled rank sums.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Convert rank sums to U\",\n     \"body\": \"U₁=R₁−n₁(n₁+1)/2; U₂=R₂−n₂(n₂+1)/2.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"Why subtract the first ranks?\",\n     \"body\": \"The smallest possible rank sum for n₁ observations is 1+2+…+n₁=n₁(n₁+1)/2.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Fixed sum\",\n     \"body\": \"U₁+U₂=n₁n₂. The conventional two-sided statistic is min(U₁,U₂); retain direction separately.\"\n    }\n   ],\n   \"table\": {\n    \"caption\": \"Symbols\",\n    \"head\": [\n     \"Symbol\",\n     \"Meaning\"\n    ],\n    \"rows\": [\n     [\n      \"N\",\n      \"n₁+n₂\"\n     ],\n     [\n      \"R₁, R₂\",\n      \"Pooled rank sums\"\n     ],\n     [\n      \"U₁, U₂\",\n      \"Group-specific U statistics\"\n     ],\n     [\n      \"U\",\n      \"min(U₁,U₂) for conventional two-sided test\"\n     ]\n    ]\n   },\n   \"flow\": {\n    \"title\": \"Mann–Whitney workflow\",\n    \"alt\": \"Check design; pool observations; rank with average ranks for ties; calculate rank sums; calculate both U statistics; infer and interpret.\",\n    \"nodes\": [\n     {\n      \"id\": \"a\",\n      \"r\": 0,\n      \"c\": 1,\n      \"label\": \"Check design\",\n      \"kind\": \"start\"\n     },\n     {\n      \"id\": \"b\",\n      \"r\": 1,\n      \"c\": 1,\n      \"label\": \"Pool observations\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"c\",\n      \"r\": 2,\n      \"c\": 1,\n      \"label\": \"Assign pooled ranks\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"d\",\n      \"r\": 3,\n      \"c\": 1,\n      \"label\": \"Find rank sums\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"e\",\n      \"r\": 4,\n      \"c\": 1,\n      \"label\": \"Calculate U values\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"f\",\n      \"r\": 5,\n      \"c\": 1,\n      \"label\": \"Infer and interpret\",\n      \"kind\": \"end\"\n     }\n    ],\n    \"edges\": [\n     {\n      \"from\": \"a\",\n      \"to\": \"b\"\n     },\n     {\n      \"from\": \"b\",\n      \"to\": \"c\"\n     },\n     {\n      \"from\": \"c\",\n      \"to\": \"d\"\n     },\n     {\n      \"from\": \"d\",\n      \"to\": \"e\"\n     },\n     {\n      \"from\": \"e\",\n      \"to\": \"f\"\n     }\n    ],\n    \"note\": \"Check the pooled rank total and U₁+U₂=n₁n₂.\"\n   }\n  },\n  {\n   \"kind\": \"worked\",\n   \"id\": \"s4\",\n   \"mins\": 10,\n   \"title\": \"June 2026 Q42: the full calculation\",\n   \"objective\": \"Calculate the Mann–Whitney statistic from the actual exam samples.\",\n   \"ask\": {\n    \"q\": \"After calculating rank sums, which checks should you make?\",\n    \"nudge\": \"Check pooled rank total and the sum of the two U values.\"\n   },\n   \"problem\": \"June 2026 Paper 2 Q42: ES scores 65, 57, 74, 43, 39, 88, 62, 69, 70, 72, 59, 60, 80, 83, 50. LC scores 85, 87, 92, 98, 90, 88, 75, 72, 60, 93, 88, 89, 96, 73, 62. Calculate U.\",\n   \"steps\": [\n    {\n     \"say\": \"Pool all 30 observations and rank them together.\",\n     \"math\": \"N=15+15=30\",\n     \"why\": \"All observations share one ordered list. Tied scores receive average pooled ranks.\"\n    },\n    {\n     \"say\": \"Add the pooled ranks for ES.\",\n     \"math\": \"R_ES=152.5\",\n     \"why\": \"The rank sum is calculated after average-rank assignment for tied scores.\"\n    },\n    {\n     \"say\": \"Convert the ES rank sum to U.\",\n     \"math\": \"U_ES=152.5−15(16)/2=152.5−120=32.5\",\n     \"why\": \"The first 15 ranks sum to 15×16/2=120.\"\n    },\n    {\n     \"say\": \"Use the fixed-sum identity.\",\n     \"math\": \"U_LC=15×15−32.5=225−32.5=192.5\",\n     \"why\": \"U_ES+U_LC must equal n_ES n_LC=225.\"\n    },\n    {\n     \"say\": \"Report the conventional two-sided statistic.\",\n     \"math\": \"U=min(32.5,192.5)=32.5\",\n     \"why\": \"This matches the 32.5 option in June 2026 Q42. ES has the lower rank sum.\"\n    }\n   ],\n   \"after\": \"Checks: pooled ranks sum to 30×31/2=465, and U values sum to 225.\"\n  },\n  {\n   \"kind\": \"recall\",\n   \"id\": \"s5\",\n   \"mins\": 3,\n   \"title\": \"Pause and recall\",\n   \"objective\": \"Retrieve the core relationships.\",\n   \"intro\": \"Answer each before revealing it.\",\n   \"items\": [\n    {\n     \"q\": \"Minimum rank sum for n observations?\",\n     \"a\": \"n(n+1)/2.\"\n    },\n    {\n     \"q\": \"What is U₁+U₂?\",\n     \"a\": \"n₁n₂.\"\n    },\n    {\n     \"q\": \"How are ties ranked?\",\n     \"a\": \"Average of occupied positions.\"\n    },\n    {\n     \"q\": \"Conventional two-sided U?\",\n     \"a\": \"The smaller of U₁ and U₂.\"\n    },\n    {\n     \"q\": \"Minimum measurement scale?\",\n     \"a\": \"Ordinal.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"completion\",\n   \"id\": \"s6\",\n   \"mins\": 8,\n   \"title\": \"Complete a rank-sum calculation\",\n   \"objective\": \"Fill the missing steps in a U calculation.\",\n   \"problem\": \"A group of size 4 has pooled rank sum R₁=30. Find U₁.\",\n   \"steps\": [\n    {\n     \"say\": \"Write the conversion formula.\",\n     \"blank\": {\n      \"prompt\": \"U₁=R₁−…\",\n      \"answer\": \"n₁(n₁+1)/2\",\n      \"accept\": [\n       \"4(5)/2\"\n      ],\n      \"hint\": \"Subtract the sum of the first four positive integers.\"\n     },\n     \"why\": \"This removes the group's minimum possible rank sum.\"\n    },\n    {\n     \"say\": \"Substitute n₁=4.\",\n     \"blank\": {\n      \"prompt\": \"4×5/2 equals …\",\n      \"answer\": \"10\",\n      \"accept\": [\n       \"10.0\"\n      ],\n      \"hint\": \"Multiply 4 and 5, then divide by 2.\"\n     },\n     \"why\": \"The first four ranks sum to 10.\"\n    },\n    {\n     \"say\": \"Finish.\",\n     \"blank\": {\n      \"prompt\": \"U₁=30−10=…\",\n      \"answer\": \"20\",\n      \"accept\": [\n       \"20.0\"\n      ],\n      \"hint\": \"Subtract 10 from 30.\"\n     },\n     \"why\": \"The result is U₁, not the rank sum.\"\n    }\n   ],\n   \"after\": \"Keep R₁ and U₁ distinct: subtract the minimum rank sum.\",\n   \"ask\": {\n    \"q\": \"Which term must be subtracted from R₁ to obtain U₁?\",\n    \"nudge\": \"Use the minimum possible rank sum n₁(n₁+1)/2.\"\n   }\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s7\",\n   \"mins\": 8,\n   \"title\": \"Null distribution and ties\",\n   \"objective\": \"State the null moments and tie correction.\",\n   \"ask\": {\n    \"q\": \"Which quantity is adjusted by the tie correction?\",\n    \"nudge\": \"The correction changes the variance, not the null mean.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"formula\",\n     \"h\": \"Null mean\",\n     \"body\": \"E(U)=n₁n₂/2.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Variance without ties\",\n     \"body\": \"Var(U)=n₁n₂(N+1)/12.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Variance with ties\",\n     \"body\": \"Var(U)=[n₁n₂/12]×[N+1−Σ(t³−t)/(N(N−1))], where t runs over tied-group sizes.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"Large-sample standardisation\",\n     \"body\": \"Z=(U−E(U))/√Var(U). A continuity correction may subtract 0.5 from |U−E(U)| before division; follow the question's convention.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Interpretation\",\n     \"body\": \"The general null compares the two distributions. A pure location or median interpretation requires similarly shaped distributions differing only by a location shift.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"guided\",\n   \"id\": \"s8\",\n   \"mins\": 8,\n   \"title\": \"Guided calculation with unequal sizes\",\n   \"objective\": \"Use the fixed-sum identity to find the second U.\",\n   \"problem\": \"Two independent groups have n₁=8 and n₂=7. A calculation gives U₁=42. Find U₂ and the smaller U.\",\n   \"hints\": [\n    \"Start with U₁+U₂=n₁n₂.\",\n    \"Calculate 8×7.\",\n    \"Subtract U₁ and compare.\"\n   ],\n   \"answer\": \"U₁+U₂=56, so U₂=14 and the smaller U is 14.\",\n   \"check\": \"The two values add to 56, equal to n₁n₂.\",\n   \"scenario\": {\n    \"teaser\": \"An ordinal outcome in two independent treatment groups.\",\n    \"title\": \"A clinical comparison\",\n    \"body\": [\n     \"A researcher allocates different patients to two independent treatment groups and records an ordinal symptom score after treatment. Each patient contributes one score and no patient appears in both groups. The response has a meaningful order, but equal numerical gaps between categories are not guaranteed. A rank-sum procedure is a reasonable candidate for a distributional comparison. If the same patients were measured before and after treatment, the data would be paired and Mann–Whitney would not respect that pairing.\"\n    ],\n    \"q\": \"What design change would make Mann–Whitney inappropriate?\",\n    \"answer\": \"Using the same patients for both measurements would make the data paired.\"\n   },\n   \"solution\": [\n    {\n     \"say\": \"Find the fixed total.\",\n     \"math\": \"n₁n₂=8×7=56\",\n     \"why\": \"The two U statistics must sum to this value.\"\n    },\n    {\n     \"say\": \"Find U₂.\",\n     \"math\": \"U₂=56−42=14\",\n     \"why\": \"Subtract U₁ from the fixed total.\"\n    },\n    {\n     \"say\": \"Select the smaller statistic.\",\n     \"math\": \"min(42,14)=14\",\n     \"why\": \"The conventional two-sided statistic is 14.\"\n    }\n   ],\n   \"ask\": {\n    \"q\": \"What identity gives U₂ once U₁ is known?\",\n    \"nudge\": \"Use U₁+U₂=n₁n₂.\"\n   }\n  },\n  {\n   \"kind\": \"trapcheck\",\n   \"id\": \"s9\",\n   \"mins\": 6,\n   \"title\": \"Six statements to challenge\",\n   \"objective\": \"Detect common design and calculation errors.\",\n   \"intro\": \"Decide true or false on all six before revealing.\",\n   \"items\": [\n    {\n     \"claim\": \"Mann–Whitney is designed for two independent samples.\",\n     \"tf\": true,\n     \"why\": \"True. Paired samples need a paired procedure.\"\n    },\n    {\n     \"claim\": \"Each sample should be ranked separately.\",\n     \"tf\": false,\n     \"why\": \"False. Pool first so ranks preserve cross-group ordering.\"\n    },\n    {\n     \"claim\": \"The two U statistics add to n₁n₂.\",\n     \"tf\": true,\n     \"why\": \"True. This is a useful arithmetic check.\"\n    },\n    {\n     \"claim\": \"Tied observations should receive arbitrary distinct ranks.\",\n     \"tf\": false,\n     \"why\": \"False. Assign the average of occupied positions.\"\n    },\n    {\n     \"claim\": \"The test always tests equality of medians regardless of distribution shape.\",\n     \"tf\": false,\n     \"why\": \"False. It compares distributions; a median interpretation needs common-shape assumptions.\"\n    },\n    {\n     \"claim\": \"The data must be at least ordinal.\",\n     \"tf\": true,\n     \"why\": \"True. The ordering must be meaningful.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"guided\",\n   \"id\": \"s10\",\n   \"mins\": 8,\n   \"title\": \"Transfer: choose the test first\",\n   \"objective\": \"Select the correct rank procedure from a paired design.\",\n   \"problem\": \"A company measures satisfaction for the same 12 employees before and after training. The response is an ordered five-category rating. Which procedure is appropriate, and why is Mann–Whitney not?\",\n   \"hints\": [\n    \"Identify whether the same people appear twice.\",\n    \"A paired rank test uses within-person differences.\",\n    \"Mann–Whitney assumes independent groups.\"\n   ],\n   \"answer\": \"Wilcoxon signed-rank is a paired rank procedure when assumptions are appropriate; the sign test is a more assumption-light alternative. Mann–Whitney ignores the pairing.\",\n   \"check\": \"The cue is the same 12 employees measured twice.\",\n   \"solution\": [\n    {\n     \"say\": \"Identify the unit.\",\n     \"math\": \"12 employees, each measured twice\",\n     \"why\": \"The two observations from one employee are linked.\"\n    },\n    {\n     \"say\": \"Choose a paired method.\",\n     \"math\": \"Within-person differences → signed-rank or sign test\",\n     \"why\": \"The analysis must preserve pairing.\"\n    },\n    {\n     \"say\": \"Reject the independent-sample method.\",\n     \"math\": \"Mann–Whitney requires independent groups\",\n     \"why\": \"Treating paired observations as independent discards the design.\"\n    }\n   ],\n   \"ask\": {\n    \"q\": \"Which design cue separates Mann–Whitney from a paired rank test?\",\n    \"nudge\": \"Check whether the same units appear in both conditions.\"\n   }\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s11\",\n   \"mins\": 6,\n   \"title\": \"Assumptions and interpretation\",\n   \"objective\": \"Interpret rejection with appropriate qualifications.\",\n   \"ask\": {\n    \"q\": \"Why is 'the medians differ' too strong as a universal interpretation?\",\n    \"nudge\": \"Two distributions can have different spreads but the same median.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"def\",\n     \"h\": \"Core conditions\",\n     \"body\": \"Independent observations within and across groups; an outcome that can be ordered; and a sampling or randomisation design supporting the chosen reference distribution.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"What rejection supports\",\n     \"body\": \"Evidence that the two population distributions differ under the null model. The difference may involve location, spread or other distributional features.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"When a median statement is justified\",\n     \"body\": \"If the distributions have the same shape and spread and differ only by a location shift, rejection supports a location and median difference. State this condition explicitly.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"recall\",\n   \"id\": \"s12\",\n   \"mins\": 3,\n   \"title\": \"Second recall\",\n   \"objective\": \"Consolidate formulas and design cues.\",\n   \"intro\": \"Answer, then reveal.\",\n   \"items\": [\n    {\n     \"q\": \"Which test for two independent groups?\",\n     \"a\": \"Mann–Whitney U.\"\n    },\n    {\n     \"q\": \"How are tied pooled ranks assigned?\",\n     \"a\": \"Average ranks.\"\n    },\n    {\n     \"q\": \"What is E(U) under H₀?\",\n     \"a\": \"n₁n₂/2.\"\n    },\n    {\n     \"q\": \"No-tie variance?\",\n     \"a\": \"n₁n₂(N+1)/12.\"\n    },\n    {\n     \"q\": \"What does U₁+U₂ equal?\",\n     \"a\": \"n₁n₂.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"summary\",\n   \"id\": \"s13\",\n   \"mins\": 3,\n   \"title\": \"What you should now be able to do\",\n   \"objective\": \"Perform and interpret a two-independent-sample rank test.\",\n   \"body\": [\n    \"Choose Mann–Whitney from the independent-sample design and ordinal measurement scale.\",\n    \"Pool observations and assign average ranks to ties.\",\n    \"Calculate R₁, R₂, U₁ and U₂, then verify both totals.\",\n    \"Use the null mean, variance and tie correction for large-sample inference.\",\n    \"Interpret rejection as a distributional difference; claim a median shift only with common-shape assumptions.\"\n   ],\n   \"ask\": {\n    \"q\": \"What is the safest one-line rule for selecting Mann–Whitney?\",\n    \"nudge\": \"Two independent groups with an ordinal-or-higher response.\"\n   }\n  },\n  {\n   \"kind\": \"quiz\",\n   \"id\": \"s14\",\n   \"mins\": 4,\n   \"title\": \"Mastery test\",\n   \"objective\": \"Demonstrate the skill independently on unseen questions.\",\n   \"setId\": \"nonparam_t1_mastery\"\n  }\n ],\n \"anchors\": [\n  {\n   \"paper\": \"j26\",\n   \"q\": 42\n  }\n ]\n}\n"
POOL_JSON = "{\n \"moduleId\": \"nonparam\",\n \"topicId\": \"nonparam-t1\",\n \"source\": \"mastery\",\n \"label\": \"Mann–Whitney U — mastery test\",\n \"count\": 20,\n \"items\": [\n  {\n   \"id\": \"np-t1-m-01\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"Which design is intended for Mann–Whitney U?\",\n   \"options\": [\n    \"Two independent groups\",\n    \"Same group measured twice\",\n    \"Three matched conditions\",\n    \"One sample against a fixed median\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"Mann–Whitney compares two independent samples. Repeated measurements require a paired procedure.\"\n  },\n  {\n   \"id\": \"np-t1-m-02\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"The response should be measured on at least which scale?\",\n   \"options\": [\n    \"Nominal\",\n    \"Ordinal\",\n    \"Ratio only\",\n    \"Normally distributed interval\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"Ordinal measurement is enough because the procedure uses ordering; nominal categories have no natural order.\"\n  },\n  {\n   \"id\": \"np-t1-m-03\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"How should tied observations be ranked?\",\n   \"options\": [\n    \"Random distinct ranks\",\n    \"Discard tied values\",\n    \"Average occupied ranks\",\n    \"Lowest occupied rank\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"Average ranks preserve the pooled rank total. A tie occupying positions 4 and 5 receives rank 4.5.\"\n  },\n  {\n   \"id\": \"np-t1-m-04\",\n   \"format\": \"numeric\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"For n₁=4 and n₂=5, U₁+U₂ equals:\",\n   \"options\": [\n    \"9\",\n    \"10\",\n    \"18\",\n    \"20\"\n   ],\n   \"answer\": \"D\",\n   \"explanation\": \"The two U statistics always sum to n₁n₂. Here 4×5=20; use this as an arithmetic check.\",\n   \"check\": \"Computed check: 20.\"\n  },\n  {\n   \"id\": \"np-t1-m-05\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"The null expectation of U is:\",\n   \"options\": [\n    \"n₁n₂/2\",\n    \"n₁+n₂\",\n    \"n₁n₂\",\n    \"N(N+1)/2\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"Under the null, the groups are exchangeable in rank allocation, so the mean of U is half of n₁n₂.\"\n  },\n  {\n   \"id\": \"np-t1-m-06\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"Which is the rank-based alternative to the two-independent-sample t test?\",\n   \"options\": [\n    \"Wilcoxon signed-rank\",\n    \"Mann–Whitney U\",\n    \"Friedman\",\n    \"Paired sign test\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"Mann–Whitney is the rank-based two-independent-sample alternative; signed-rank and paired sign tests use linked observations.\"\n  },\n  {\n   \"id\": \"np-t1-m-07\",\n   \"format\": \"numeric\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"A group has n₁=6 and pooled rank sum R₁=30. Find U₁.\",\n   \"options\": [\n    \"5\",\n    \"6\",\n    \"9\",\n    \"15\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"U₁=30−6×7/2=30−21=9. Do not report the rank sum itself as U.\",\n   \"check\": \"Computed check: 9.\"\n  },\n  {\n   \"id\": \"np-t1-m-08\",\n   \"format\": \"numeric\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"For n₁=8, n₂=7 and U₁=42, find U₂.\",\n   \"options\": [\n    \"12\",\n    \"14\",\n    \"42\",\n    \"56\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"U₁+U₂=8×7=56. Hence U₂=56−42=14; the smaller statistic is 14.\",\n   \"check\": \"Computed check: 14.\"\n  },\n  {\n   \"id\": \"np-t1-m-09\",\n   \"format\": \"numeric\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"For n₁=5 and n₂=6, the null mean of U is:\",\n   \"options\": [\n    \"11\",\n    \"15\",\n    \"30\",\n    \"60\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"E(U)=5×6/2=15. The product 30 is the sum of U₁ and U₂, not the mean.\",\n   \"check\": \"Computed check: 15.\"\n  },\n  {\n   \"id\": \"np-t1-m-10\",\n   \"format\": \"numeric\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"For n₁=5, n₂=6, N=11 and no ties, Var(U) is:\",\n   \"options\": [\n    \"15\",\n    \"25\",\n    \"30\",\n    \"35\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"Var(U)=5×6×(11+1)/12=30. The null mean is 15; U₁+U₂ is 30.\",\n   \"check\": \"Computed check: 30.\"\n  },\n  {\n   \"id\": \"np-t1-m-11\",\n   \"format\": \"single\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"A pooled tie occupies ranks 7, 8 and 9. What rank is assigned to each tied value?\",\n   \"options\": [\n    \"7\",\n    \"8\",\n    \"9\",\n    \"8.5\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"The average occupied position is (7+8+9)/3=8. Average ranking preserves the total rank sum.\"\n  },\n  {\n   \"id\": \"np-t1-m-12\",\n   \"format\": \"multi\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"Which statements about the two U statistics are correct? A. U₁+U₂=n₁n₂. B. Both U values are nonnegative. C. The conventional two-sided statistic is the smaller U. D. U₁ must equal U₂.\",\n   \"options\": [\n    \"A, B and C only\",\n    \"A and D only\",\n    \"B and D only\",\n    \"A, B, C and D\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"A is the fixed-sum identity; B follows from the pairwise-order interpretation; C is the conventional two-sided choice. D is not generally true.\",\n   \"statements\": [\n    \"U₁+U₂=n₁n₂.\",\n    \"Both U values are nonnegative.\",\n    \"The conventional two-sided statistic is min(U₁,U₂).\",\n    \"U₁ must equal U₂.\"\n   ],\n   \"verdicts\": {\n    \"A\": {\n     \"tf\": true,\n     \"why\": \"True: the two rank-sum expressions add to n₁n₂.\"\n    },\n    \"B\": {\n     \"tf\": true,\n     \"why\": \"True: U counts pairwise orderings, with half contributions for ties.\"\n    },\n    \"C\": {\n     \"tf\": true,\n     \"why\": \"True: the smaller value is used for the conventional two-sided statistic.\"\n    },\n    \"D\": {\n     \"tf\": false,\n     \"why\": \"False: the U values need only add to n₁n₂; they need not be equal.\"\n    }\n   }\n  },\n  {\n   \"id\": \"np-t1-m-13\",\n   \"format\": \"single\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"The no-tie null variance of U is:\",\n   \"options\": [\n    \"n₁n₂(N+1)/12\",\n    \"n₁n₂/2\",\n    \"(N−1)/12\",\n    \"n₁n₂(N−1)/2\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"The no-tie variance is n₁n₂(N+1)/12. When ties are present, use the tie-corrected variance.\"\n  },\n  {\n   \"id\": \"np-t1-m-14\",\n   \"format\": \"single\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"The same people are measured before and after training. Which procedure is appropriate for paired ordinal differences?\",\n   \"options\": [\n    \"Mann–Whitney U\",\n    \"Kruskal–Wallis\",\n    \"Wilcoxon signed-rank or sign test\",\n    \"Two-sample pooled t\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"The observations are linked within person. A paired procedure analyses within-person differences; Mann–Whitney assumes independent groups.\"\n  },\n  {\n   \"id\": \"np-t1-m-15\",\n   \"format\": \"numeric\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"A sample of size 12 has pooled rank sum R₁=100. Find U₁.\",\n   \"options\": [\n    \"22\",\n    \"28\",\n    \"78\",\n    \"100\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"U₁=100−12×13/2=100−78=22. This tests the rank-sum conversion.\",\n   \"check\": \"Computed check: 22.\"\n  },\n  {\n   \"id\": \"np-t1-m-16\",\n   \"format\": \"single\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"When ties are present, the large-sample variance is adjusted by:\",\n   \"options\": [\n    \"Adding Σ(t³−t) to variance\",\n    \"Multiplying by 1−Σ(t³−t)/(N³−N)\",\n    \"Replacing N by distinct-value count\",\n    \"No adjustment is needed\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"The tie correction factor is 1−Σ(t³−t)/(N³−N), where t is each tied-group size.\"\n  },\n  {\n   \"id\": \"np-t1-m-17\",\n   \"format\": \"multi\",\n   \"diff\": \"hard\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"Which statements about interpretation are defensible? A. The null compares distributions. B. Rejection always proves unequal medians. C. A common-shape location shift supports a median interpretation. D. A spread difference can contribute to rejection.\",\n   \"options\": [\n    \"A, C and D only\",\n    \"A and B only\",\n    \"B and C only\",\n    \"A, B, C and D\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"The general null concerns distributions. A common-shape location shift supports a median interpretation; spread differences can also create distributional differences.\",\n   \"statements\": [\n    \"The null compares the two population distributions.\",\n    \"Rejection always proves unequal medians.\",\n    \"A common-shape location shift supports a median interpretation.\",\n    \"A spread difference can contribute to rejection.\"\n   ],\n   \"verdicts\": {\n    \"A\": {\n     \"tf\": true,\n     \"why\": \"True: the general null is equality or exchangeability of the two distributions.\"\n    },\n    \"B\": {\n     \"tf\": false,\n     \"why\": \"False: differing shapes or spreads can also produce a distributional difference.\"\n    },\n    \"C\": {\n     \"tf\": true,\n     \"why\": \"True: under a common-shape location shift, a median interpretation is justified.\"\n    },\n    \"D\": {\n     \"tf\": true,\n     \"why\": \"True: the test is not universally a pure median test.\"\n    }\n   }\n  },\n  {\n   \"id\": \"np-t1-m-18\",\n   \"format\": \"numeric\",\n   \"diff\": \"hard\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"For n₁=10, n₂=12 and N=22, calculate the no-tie Var(U).\",\n   \"options\": [\n    \"110\",\n    \"220\",\n    \"230\",\n    \"240\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"Var(U)=10×12×23/12=230. The null mean is 60 and U₁+U₂=120.\",\n   \"check\": \"Computed check: 230.\"\n  },\n  {\n   \"id\": \"np-t1-m-19\",\n   \"format\": \"single\",\n   \"diff\": \"hard\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"Why is Mann–Whitney not automatically a test of medians?\",\n   \"options\": [\n    \"It uses means rather than ranks\",\n    \"It requires normal populations\",\n    \"It compares distributions; shape and spread can differ\",\n    \"It is valid only for equal sample sizes\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"The rank-sum test is sensitive to distributional differences more generally. A median/location conclusion requires a common-shape assumption.\"\n  },\n  {\n   \"id\": \"np-t1-m-20\",\n   \"format\": \"single\",\n   \"diff\": \"hard\",\n   \"topic\": \"nonparam-t1\",\n   \"stem\": \"For June 2026 Q42, how are the 30 observations ranked?\",\n   \"options\": [\n    \"Rank each group separately\",\n    \"Convert scores to z-scores\",\n    \"Remove repeated scores\",\n    \"Pool all 30 scores and rank together, averaging ties\"\n   ],\n   \"answer\": \"D\",\n   \"explanation\": \"The groups are compared through positions in the combined ordering. Repeated score values receive average pooled ranks.\"\n  }\n ]\n}\n"
